-- =====================================================================
-- Test del Nivel 0 · banco de preguntas de texto fijo
-- Los textos de pagos vienen del quiz de la lista general; los de
-- Empiece Ya, comisiones y objeciones, de las indicaciones de Nelson.
-- Se reescribe con "on conflict do update" para poder corregir textos.
-- =====================================================================

insert into public.ts_banco (id, paso, texto, correctas, incorrectas, n_incorrectas, logica) values

-- ---------------- Inicial, saldo y cuotas ----------------
('medios_inicial_1', 'medios_inicial',
 '¿Por qué medios puede el cliente entregar la inicial? (marca todas las respuestas válidas)',
 '["Yape a tu número (luego lo depositas a Rena Ware)", "Te lo entrega en efectivo", "Transferencia a las cuentas de Rena Ware", "Tarjeta, con un link de pago que pides a tu líder"]',
 '["Criptomonedas", "Cheque a fecha", "Pagaré firmado"]', 1,
 'Repasa los medios válidos para la inicial: Yape a tu número (luego lo depositas a Rena Ware), te lo entrega en efectivo, transferencia a las cuentas de Rena Ware, o tarjeta con un link de pago que pides a tu líder. Identifícalos e inténtalo de nuevo.'),

('prepago_1', 'prepago',
 '¿El cliente puede adelantar el pago de su crédito?',
 '["Sí. Dentro de los 30 días de recibir su pedido paga el precio contado; después, cada adelanto le baja el interés."]',
 '["No: debe pagar sus cuotas tal como están en el cronograma, sin adelantar nada.", "Sí, pero paga una penalidad por adelantar y el interés completo igual.", "Solo si Rena Ware lo autoriza por escrito, y después de seis meses.", "Sí, pero los intereses se cobran completos aunque adelante el pago."]', 4,
 'Adelantar siempre le conviene al cliente: dentro de los 30 días de la entrega paga el precio contado, sin interés; y después, cada adelanto reduce el interés.'),
('prepago_2', 'prepago',
 'Un cliente compró a 12 cuotas y, a las 3 semanas de recibir su pedido, quiere pagar todo. ¿Qué pasa?',
 '["Paga el saldo al precio contado: dentro de los 30 días de la entrega no paga interés."]',
 '["Tiene que pagar las 12 cuotas completas, con todo su interés incluido.", "No puede: debe esperar a que termine su crédito para cancelarlo.", "Paga el saldo más una penalidad del 10 % por cancelar antes.", "Solo puede adelantar una cuota por mes, nunca el total de golpe."]', 4,
 'Dentro de los 30 días de recibir su pedido, el cliente puede cancelar todo al precio contado, sin interés. Pasado ese plazo, igual puede adelantar y paga menos interés.'),

-- ---------------- Crédito y zonas ----------------
('caso_100_1', 'caso_100',
 'Además de los pedidos de S/ 500 o menos, ¿en qué otro caso el cliente debe pagar el 100 %?',
 '["Cuando el cliente vive en una zona donde no hay crédito."]',
 '["Cuando compra más de tres productos a la vez.", "Cuando paga la inicial con tarjeta.", "Cuando el producto es de una promoción especial.", "Cuando es la primera compra del cliente."]', 4,
 'En zonas sin crédito no hay entregador: el pedido va por Courier, que no recibe pagos. Por eso se paga el total por adelantado. El cliente puede dar el 10 % para ingresar el pedido, pero para despacharlo debe mandar la constancia del pago del saldo.'),
('caso_100_2', 'caso_100',
 'Un cliente de una zona sin crédito da el 10 % de inicial. ¿Qué tiene que pasar para que le despachen su pedido?',
 '["Debe depositar el saldo a Rena Ware antes del despacho: en esas zonas se paga el 100 %."]',
 '["Nada: paga el saldo contra entrega al entregador, como en cualquier zona.", "Debe firmar un contrato de crédito especial para zonas alejadas.", "Debe dar una segunda inicial del 10 % antes de que salga el pedido.", "Lo despachan igual y el saldo lo paga en cuotas con su contrato."]', 4,
 'En zonas sin crédito no hay entregador que cobre: el pedido va por Courier. Por eso el saldo se deposita a Rena Ware antes del despacho.'),

-- ---------------- Cuentas y pagos ----------------
('medios_saldo_1', 'medios_saldo',
 'Al pagar el saldo contra entrega, ¿qué medios puede usar el cliente? (marca todas las respuestas válidas)',
 '["Efectivo al entregador", "Tarjeta (el entregador lleva POS)", "Transferencia a Rena Ware y mostrar el voucher", "Yape al entregador (si el monto no es alto)"]',
 '["Cheque al entregador", "Con el número de contrato de otro cliente"]', 1,
 'Repasa los medios válidos para el saldo contra entrega: efectivo al entregador, tarjeta (POS del entregador), transferencia a Rena Ware mostrando el voucher, o Yape al entregador si el monto no es alto.'),

('pago_cuotas_1', 'pago_cuotas',
 'Si el cliente compró en cuotas, ¿cómo paga la cuota mensual?',
 '["Con su número de contrato, en cualquier agente o aplicativo del BCP, BBVA o Interbank."]',
 '["Solo en efectivo, en la oficina de Rena Ware, de lunes a viernes.", "Transfiriendo cada mes a la cuenta personal de su líder o asesor.", "Únicamente con tarjeta, con un link de pago que pide a la oficina.", "Por Yape al número personal de su asesor, que luego lo deposita."]', 4,
 'Las cuotas se pagan con el número de contrato del cronograma: por Yape (pago de servicios), por la app del banco, o en cualquier agente o agencia (BCP, BBVA o Interbank). Para pagar más se usa «otra cobranza»; para pagar todo, «pronto pago».'),
('pago_cuotas_2', 'pago_cuotas',
 'Tu cliente quiere pagar su cuota desde su celular. ¿Qué necesita?',
 '["Su número de contrato: paga en el aplicativo del BCP, BBVA o Interbank, o por Yape en pago de servicios."]',
 '["Tu número de Yape, para que tú le hagas el pago cada mes a Rena Ware.", "El número de cuenta personal de su líder, para transferirle la cuota.", "Un link de pago nuevo que se pide a la oficina al comienzo de cada mes.", "Nada: desde el celular no se puede, la cuota solo se paga en la oficina."]', 4,
 'Las cuotas se pagan con el número de contrato del cronograma, en el aplicativo o agente del BCP, BBVA o Interbank, o por Yape en pago de servicios.'),

-- ---------------- Empiece Ya ----------------
('ey_rol_1', 'ey_rol',
 'Afiliaste a alguien nuevo. ¿Qué te toca hacer con su Empiece Ya?',
 '["Explicárselo y hacerle seguimiento hasta su último día: «te faltan 3 semanas… te quedan 5 días»."]',
 '["Nada: cada quien ve su propio programa y su plazo con la oficina.", "Explicárselo bien el primer día; después ya depende solo de él.", "Avisarle al final, cuando ya se cumpla su plazo, para ver si ganó.", "Pedirle a la oficina que se lo explique y que le haga el seguimiento."]', 4,
 'Es parte de tu rol: a cada afiliado le explicas su Empiece Ya y lo acompañas hasta su último día, recordándole cuánto tiempo le queda. Sus puntos también suman a tu grupo.'),
('ey_rol_2', 'ey_rol',
 'A tu afiliada le quedan 5 días de su Empiece Ya y todavía no logra su nivel. ¿Qué haces?',
 '["Le escribes «te quedan 5 días» y la ayudas a sacar citas para lograrlo."]',
 '["Nada: ella ya sabe su plazo y es su responsabilidad lograrlo.", "Esperas a que termine su plazo para ver en los resultados si ganó.", "Le dices que con tan pocos días ya no se puede, que será otra vez.", "Le pides a otra persona del equipo que le avise cuando pueda."]', 4,
 'Tu rol es acompañar a cada afiliado hasta su último día: recordarle cuánto le queda («te faltan 3 semanas», «te faltan 2», «te quedan 5 días») y ayudarlo a lograrlo.'),

-- ---------------- Comisiones y autocompra ----------------
('com_donde_1', 'com_donde',
 '¿Dónde encuentras cuánto ganas de comisión y cuántos puntos da cada producto o promoción?',
 '["En el cuadro de comisiones, al final de la lista de precios"]',
 '["En el catálogo de productos, junto a cada foto", "En la boleta o factura que recibe el cliente", "Te lo dice Rena Ware recién cuando te paga", "En el contrato de crédito que firma el cliente"]', 4,
 'El cuadro de comisiones está al final de cada lista de precios: por cada código ves su valor comisionable y sus puntos.'),
('com_donde_2', 'com_donde',
 'Quieres saber los puntos y el valor comisionable de una promoción. ¿Dónde los buscas?',
 '["En el cuadro de comisiones, al final de su lista de precios"]',
 '["En la foto de la promoción, debajo del precio", "En el catálogo de productos, al lado de cada foto", "En la boleta de venta que se entrega al cliente", "Se los preguntas a la oficina cada vez que vendes"]', 4,
 'Cada lista trae al final su cuadro de comisiones: ahí ubicas el código y lees su valor comisionable y sus puntos.'),
('com_pct_1', 'com_pct',
 '¿Cuánto es tu comisión de venta?',
 '["El 15 % del valor comisionable"]',
 '["El 15 % del precio de venta", "El 10 % del precio de venta", "El 30 % del valor comisionable", "El 15 % de la inicial que da el cliente"]', 4,
 'La comisión no se calcula sobre el precio: se calcula sobre el valor comisionable que aparece en el cuadro de comisiones. Repasa el porcentaje en Precios y promociones → «Cuánto gano con esta venta».'),
('com_pct_2', 'com_pct',
 'Una promoción tiene un valor comisionable de S/ 4,000. ¿Cuánto es tu comisión?',
 '["S/ 600"]',
 '["S/ 400", "S/ 1,200", "S/ 708", "S/ 150"]', 4,
 'La comisión es un porcentaje del valor comisionable (no del precio). Repasa cuál es en Precios y promociones → «Cuánto gano con esta venta» y aplícalo.'),
('auto_que_1', 'auto_que',
 '¿Qué pasa cuando te autocompras (compras para ti o tu familia)?',
 '["Te descuentan tu comisión (por 1.18): te sale más barato y los puntos cuentan para tus premios"]',
 '["Pagas el precio normal y la comisión te la depositan al mes siguiente", "Te sale más barato, pero esos puntos ya no cuentan para tus premios", "No se puede: la comisión solo se gana vendiéndole a otras personas", "Te descuentan el 15 % del precio de lista, pero no te suma puntos"]', 4,
 'Precio de autocompra = precio de cliente − (comisión × 1.18). Y esa compra suma puntos para tu Empiece Ya.'),
('auto_que_2', 'auto_que',
 '¿Cómo se calcula tu precio de autocompra?',
 '["Precio de cliente menos tu comisión por 1.18"]',
 '["Precio de cliente menos el 15 % del precio", "Precio de cliente menos el 10 % del precio", "Es el mismo precio que paga cualquier cliente", "Precio de cliente menos los S/ 70 de tu afiliación"]', 4,
 'Tu comisión es el 15 % del valor comisionable (cuadro de comisiones). Por 1.18 da tu descuento: precio de autocompra = precio de cliente − (comisión × 1.18).'),

-- ---------------- Frase de oro y objeciones ----------------
('frase_oro_1', 'frase_oro',
 '¿Cuál es la frase de oro para sacar una cita?',
 '["«Estoy trabajando en Rena Ware. ¿Has escuchado de Rena Ware?»"]',
 '["«¿Le interesa comprar unas ollas de acero quirúrgico?»", "«Tengo una oferta que no va a poder rechazar.»", "«¿Me ayudas con una venta para cumplir mi meta?»", "«¿Tiene un minuto para una encuesta?»"]', 4,
 'La frase de oro abre la conversación sin vender: cuentas a qué te dedicas y preguntas si ha escuchado de Rena Ware. El objetivo es sacar la cita, no convencer.'),
('frase_oro_2', 'frase_oro',
 'Te encuentras con una conocida y te pregunta: «¿Y a qué te dedicas ahora?». ¿Qué le dices?',
 '["«Estoy trabajando en Rena Ware. ¿Has escuchado de Rena Ware?»"]',
 '["«Vendo ollas, ¿me compras una?»", "«A nada en especial, ahí nomás.»", "«Te cuento después, que es largo.»", "«Tengo una promoción buenísima, ¿la quieres?»"]', 4,
 'Es el momento de la frase de oro: cuentas que trabajas en Rena Ware y preguntas si ha escuchado. Así abres la conversación para sacar la cita.'),
('objeciones_3_1', 'objeciones_3',
 '¿Cuáles son las 3 objeciones que más te van a decir al sacar una cita?',
 '["«Es caro», «Ya tengo» y «Se me quema todo / necesito un repuesto»"]',
 '["«No me gusta el acero», «No cocino» y «Vivo lejos»", "«No tengo tiempo», «No conozco la marca» y «No uso ollas»", "«Mi esposo decide», «Ya compré otra marca» y «No me gustan las visitas»", "Ninguna: si la frase de oro es buena, nadie pone objeciones"]', 4,
 'Las 3 que más vas a escuchar son «es caro», «ya tengo» y «se me quema todo / necesito un repuesto / no me instalaron el filtro». Para cada una hay una respuesta que lleva a la cita.'),
('obj_caro_1', 'obj_caro',
 'Te dicen: «Es caro». ¿Qué respondes?',
 '["«Mi objetivo es dar a conocer: solo por ver participas en un sorteo. ¿Te parece hoy o mañana?»"]',
 '["«No es caro: con todo lo que trae y las cuotas, al final sale barato.»", "«Mira, vale la pena: es una inversión para toda la vida, te va a durar.»", "«Si me compras hoy te hago un descuento especial, solo por esta semana.»", "«Bueno, no te preocupes; cuando tengas plata me avisas y te visito.»"]', 4,
 'No intentes convencer. El objetivo es la cita: quitas la presión de comprar (solo es ver, y participa en un sorteo) y cierras con doble alternativa: hoy o mañana.'),
('obj_caro_2', 'obj_caro',
 'Te dicen: «Ahorita no tengo dinero para eso». ¿Qué respondes?',
 '["«Tranquila, no es para que compres: doy a conocer, y solo por ver participas en un sorteo. ¿Hoy o mañana?»"]',
 '["«Lo puedes pagar en cuotas cómodas; al mes te sale baratísimo, de verdad.»", "«Vale la pena el esfuerzo; si no lo compras ahora, después te arrepientes.»", "«Entonces no te preocupes, te busco el próximo año, cuando estés mejor.»", "«Pídele prestado a alguien de tu familia; es una buena inversión, créeme.»"]', 4,
 'El objetivo no es vender en ese momento sino sacar la cita: quitas la presión de comprar, ofreces el sorteo por ver y cierras con doble alternativa.'),
('obj_tengo_1', 'obj_tengo',
 'Te dicen: «Ya tengo Rena Ware». ¿Qué respondes?',
 '["«¿Ya te dieron tu regalo de aniversario? Estoy a cargo de esta zona: te lo llevo sin compromiso, con las promociones.»"]',
 '["«Vale la pena tener más: hay muchas opciones nuevas en el catálogo que todavía no tienes.»", "«Pero seguro no tienes el filtro; te falta eso para completar tu equipo, te lo recomiendo.»", "«Ah, qué bueno; entonces ya no necesitas nada de nada. Muchas gracias por tu tiempo.»", "«Lo nuevo es mucho mejor que lo que tienes; te conviene renovarlo de una vez, de verdad.»"]', 4,
 'Un cliente es tu mejor cita: no se le convence, se le visita con su regalo y las promociones. Le preguntas si ya le dieron su regalo de aniversario y te ofreces a llevárselo.'),
('obj_tengo_2', 'obj_tengo',
 'Te dicen: «Mi mamá ya tiene Rena Ware». ¿Qué respondes?',
 '["«¡Qué bueno! ¿Ya le dieron su regalo de aniversario? Se lo llevo sin compromiso, con las promociones. ¿Hoy o mañana?»"]',
 '["«Entonces a ti no te interesa, ¿verdad? Igual muchas gracias por escucharme un ratito.»", "«Pero tú también necesitas el tuyo propio; vale la pena tenerlo en tu casa, créeme.»", "«Lo de tu mamá ya es antiguo; el modelo nuevo es mucho mejor y te conviene más a ti.»", "«Dile a tu mamá que me llame cuando necesite algo; le dejo mi número contigo, ¿ya?»"]', 4,
 'Que ya tengan Rena Ware es una puerta, no un final: ofreces llevar su regalo de aniversario sin compromiso y las promociones, y agendas la visita.'),
('obj_repuesto_1', 'obj_repuesto',
 'Te dicen: «Se me quema todo», «Necesito un repuesto» o «No me instalaron el filtro». ¿Qué respondes?',
 '["«Para eso estamos los asesores: yo te apoyo con eso. ¿Te parece si te visito hoy o mañana?»"]',
 '["«Seguro no lo usas bien; hay que seguir las instrucciones del manual al pie de la letra.»", "«Algún día sería bueno que alguien te explique bien cómo usarlo, para que no se queme.»", "«Llama a la central de Rena Ware; ellos son los que atienden esos casos, no yo.»", "«Eso no es culpa mía; yo recién empiezo y no fui quien te vendió ese equipo.»"]', 4,
 'No te defiendas ni lo dejes para «algún día»: ofreces tu apoyo como asesor y agendas la visita con doble alternativa (hoy o mañana).'),
('obj_repuesto_2', 'obj_repuesto',
 'Te dicen: «A mí nunca me instalaron el filtro». ¿Qué respondes?',
 '["«Para eso estamos los asesores: yo te ayudo con lo de tu filtro. ¿Te visito hoy o mañana?»"]',
 '["«Qué raro, eso no debería pasar; seguro fue un error de la empresa.»", "«Algún día deberías pedir que te lo instalen, cuando tengas tiempo.»", "«Eso lo tienes que reclamar tú directamente a la empresa, por escrito.»", "«No eres mi cliente, así que yo no puedo hacer nada por ti, lo siento.»"]', 4,
 'Cuando alguien necesita apoyo, la respuesta es ofrecerlo y agendar: «para eso estamos los asesores», y cierras con hoy o mañana.')

on conflict (id) do update set
  paso = excluded.paso, texto = excluded.texto, correctas = excluded.correctas,
  incorrectas = excluded.incorrectas, n_incorrectas = excluded.n_incorrectas,
  logica = excluded.logica, actualizado_en = now();
